// packages/core/utils/dom/dom.js:292  — only filters null / undefined
export const spreadProps = ( conditions ) =>
  Object.keys( conditions ).reduce( ( acc, k ) => {
    const c = conditions[k];
    if ( c !== undefined && c !== null ) acc[k] = c;   // <- nothing DOM-relevant is filtered
    return acc;
  }, {} );

// packages/core/components/LayerHost/LayerHost.js:377  — splats the whole store module
<Content { ...spreadProps( { ...localProps } ) } displayName={ localProps.moduleName } … />
//          ^ localProps === componentManager.byId[id].data  (moduleName, _parentModules,
//            _isPrepareForCacheExecuted, anchorId, action:{…} — all of it)

// packages/external/web-palette/src/components/Link/Link.jsx:163  — the DOM sink
const linkProps = { className, target, ref, id, ...conditionalProps, ...other };
return ( <a { ...linkProps }> … </a> );   // ...other lands moduleName/action/etc on <a>

// line 21-43: closed destructure, then ...other swallows EVERYTHING else
const {
  ariaLabel, children, className, disabled, href, iconName, id, label,
  linkRef, size, tabIndex, target, textStyle, variant,
  ...other                       // <- action, moduleName, navigationType, … all in here
} = props;

// line 111-118
const linkProps = { className, target, ref: linkRef, id, ...conditionalProps, ...other };
// line 163
return ( <a { ...linkProps }> … </a> );    // ...other reaches the native <a>

// FIX (kills #1 AND #3):
//  1. add action, formAction, formMethod, formEncType, formTarget to the destructure
//     so React 19's reserved `action` can never fall through to <a>/<button>
//  2. do not spread raw ...other — run it through domSafeProps() (keep data-*/aria-*/known HTML)
//  3. in getLinkHtml.js:46 / getButtonHtml.js:37, forward via linkAction={action} not action={action}

// line 67-74: author suppressed `action` but NOT `primaryAction`
const productCardComponent = (
  <MiniProductCard { ...spreadProps( { ...product } ) } htmlTag='h3'
    eyebrow={ productTag } action={ null } />   // primaryAction (from ...product) still set
);

// line 110-116: outer <a> wraps a card that renders its own inner <a>
{ linkAction ? (
  <Link_Huge action={ linkAction } className='BoughtTogetherItem__link'>
    { productCardComponent }   // → ProductCardHorizontal → PalProductCardHorizontal → inner <a>
  </Link_Huge>
) : productCardComponent }

// FIX: pass primaryAction={ null } fullyClickable={ false } on MiniProductCard
//      (or drop the outer Link_Huge and push linkAction down as primaryAction)

// BEFORE — setState on LayerHost during BoughtTogether render
if ( !hasItems( items ) ) {
  setShowSpacer( false );   // setShowSpacer = useState owned by LayerHost.js:113, passed at :389
  return null;
}

// AFTER — move the write into an effect
useEffect( () => {
  if ( !hasItems( items ) && typeof setShowSpacer === 'function' ) setShowSpacer( false );
}, [ items, setShowSpacer ] );
if ( !hasItems( items ) ) return null;
